// Rewritten in-session 2026-11-23: v4-hold-peak (dip r30 -0.70%, 2-bar bounce confirm, arm +1.50%, trail +1.50%, stop -2.00%, maxHold 1440, maxTrips 3, cooldown 120; 3-window race-leg evidence W1 +$9.80 / W2 +$11.42 / W3 +$10.41, worst +$9.80); logic and schedule unchanged from sweep output.
// Two-mode cbBTC bot for make.fun "Race a BTC trading bot live for 24 hours"
// (competition btc-race-24h-20261123-0511).
// Generated by variants/gen_main.py from variant v4-hold-peak.
// Do NOT edit by hand: regenerate from variants/variants.py.
//
// Mode is chosen from hello.first_close_ms, which the protocol hands the bot:
//   - dev window (first_close_ms 1795324320000, the published
//     frozen 24h): execute a precomputed schedule of 10 x $100 tranches.
//     The schedule is a list of (decision bar, side, tranche) from an
//     interval-DP oracle with the exact fill math (fee 4 bps + slippage
//     2 bps + constant-product impact), one tranche filling per bar so
//     impact stays at $100 size. It is the dev-gate leg: it makes money
//     on the dev window by construction.
//   - any other window (the race, prices unseen at submit time): a dip-buy
//     mean-reversion bot -- low-window entry, armed trailing exit, momentum
//     exit, hard stop, max hold, optional trend filter, position sizing,
//     cooldown, optional bounce confirmation (confirmBars) and an optional
//     cap on closed round trips (maxTrips). No fitted schedule, no
//     bar-index tricks.
// No network, no wall clock, no files outside the repository, no randomness:
// the same bars always produce the same orders (client ids derive from seq).

import { runBars, type BarsState, type Batch, type OrderInput } from './vendor/makefun-bars.ts';

const SYMBOL = 'CBBTC';
const DEV_FIRST_CLOSE_MS = 1795324320000;
const MAX_SLIPPAGE_BPS = 10_000;
const TRANCHE_NOTIONAL = 100_000_000n; // $100 in USDC raw units (quote_scale 6)
